    (hPplane : ∀ p ∈ P, ∀ q ∈ P, linOf N (p - q) = 0) :
    vectorSpan ℚ P ≤ LinearMap.ker (linOf N)

theorem halfspace_eq_of_pos_smul {f g : Point →ᵃ[ℚ] ℚ} {lam : ℚ}
    (hlam : 0 < lam) (hfg : f = lam • g) :
    {x : Point | 0 ≤ f x} = {x : Point | 0 ≤ g x}

theorem tie_zero_of_carrier_ratio {t u : Triangle} {κ : ℚ}
    (hcN : carrierNormal t = κ • carrierNormal u) (hcD : detOrigin t = κ * detOrigin u) :
    detOrigin u • carrierNormal t - detOrigin t • carrierNormal u = 0

