theorem triangleSet_subset_facePlane (t : Triangle) :
    triangleSet t ⊆ {x : Point |
      crossProduct ((t.v₁ : Point) - t.v₀) ((t.v₂ : Point) - t.v₀) ⬝ᵥ (x - t.v₀) = 0}

private theorem winding_eq_finSum (w : Chain) (Q : Point) :
    winding w Q
      = ∑ i : Fin w.size, (if Q ∈ simplex w[i].2 then w[i].1 else 0)

private theorem winding_eq_finSum_indicator (w : Chain) (Q : Point) :
    winding w Q
      = ∑ i : Fin w.size, w[i].1 * (if Q ∈ simplex w[i].2 then (1 : ℤ) else 0)

theorem tetra_Hrep (t : Triangle)
    (h : AffineIndependent ℚ ![(0 : Point), t.v₀, t.v₁, t.v₂]) :
    simplex t = ⋂ k : Fin (tetraHalves t).size, {x : Point | 0 ≤ gOf (tetraHalves t)[k] x}

theorem tetra_Hrep_mem (t : Triangle)
    (h : AffineIndependent ℚ ![(0 : Point), t.v₀, t.v₁, t.v₂]) :
    simplex t = ⋂ g ∈ tetraHalves t, {x : Point | 0 ≤ gOf g x}

theorem tripleVertex_active {G : Array Half} {a b c : Nat}
    (ha : a < G.size) (hb : b < G.size) (hc : c < G.size) {p : Point}
    (hsome : tripleVertex G a b c = some p) :
    det3 G[a].n G[b].n G[c].n ≠ 0
      ∧ gOf G[a] p = 0 ∧ gOf G[b] p = 0 ∧ gOf G[c] p = 0

theorem exists_aff_indep_triple_of_dim2 {P : Set Point}
    (hdim : Module.finrank ℚ (vectorSpan ℚ P) = 2) :
    ∃ p : Fin 3 → Point, (∀ i, p i ∈ P) ∧ AffineIndependent ℚ p

theorem onPlane_imp_gi_zero (s t : Triangle) {i : Nat} {gi : Half}
    (hgi : (Gfun s t)[i]? = some gi) {p : Point}
    (h : onPlane (Gfun s t) i p = true) : (gOf gi) p = 0

theorem gi_zero_imp_onPlane (s t : Triangle) {i : Nat} {gi : Half}
    (hgi : (Gfun s t)[i]? = some gi) {p : Point} (h : (gOf gi) p = 0) :
    onPlane (Gfun s t) i p = true

theorem cell_eq_iInter_gAug (s t : Triangle) {i : Nat} {gi : Half}
    (_hgi : (Gfun s t)[i]? = some gi) (houter : 0 < (gOf gi) 0)
    (hdim : Module.finrank ℚ
      (vectorSpan ℚ ({x : Point | (gOf gi) x = 0} ∩ Kpair s t)) = 2) :
    ({x : Point | (gOf gi) x = 0} ∩ Kpair s t) = ⋂ j, {x | 0 ≤ gAug s t gi j x}

theorem nonvacuous_aug_imp_castAdd (s t : Triangle) {gi : Half} {N o : Point}
    (hNgi : N = gi.n) (hN : N ≠ 0) {j : Fin ((Gfun s t).size + 2)}
    (hnv : Proof.HpolytopeVertex.NonVacuous ((gAug s t gi j).comp (iotaAff N o))) :
    ∃ j' : Fin (Gfun s t).size, j = Fin.castAdd 2 j'

theorem gin_ne_zero_of_facetVert (s t : Triangle) {i : Nat} {gi : Half}
    (hgi : (Gfun s t)[i]? = some gi) (houter : 0 < (gOf gi) 0)
    {a : Point} (ha : a ∈ facetVerts (Gfun s t) i) : gi.n ≠ 0

theorem Gtil_gOf_zero_set (s t : Triangle) {n : Nat} (hn : n < (Gfun s t).size) :
    {x : Point | (SimImplCover.Gtil s t ⟨n, hn⟩) x = 0}
      = {x : Point | (gOf (Gfun s t)[n]) x = 0}

theorem relB_false_iff (s t : Triangle) (hco : ¬ Coplanar ℚ (Kpair s t))
    {j i : Nat} (hj : j < (Gfun s t).size) (hi : i < (Gfun s t).size)
    (houtj : isOuter2D (Gfun s t) j = true) (houti : isOuter2D (Gfun s t) i = true) :
    relB (Gfun s t) j i = false
      ↔ {x : Point | (SimImplCover.Gtil s t ⟨j, hj⟩) x = 0}
          ≠ {x : Point | (SimImplCover.Gtil s t ⟨i, hi⟩) x = 0}

private theorem winding_eq_zero_of_not_mem {c : Chain} {K : Set Point} {Q : Point}
    (hsub : ∀ e ∈ c.toList, simplex e.2 ⊆ K) (hQ : Q ∉ K) :
    winding c Q = 0

private theorem winding_eq_card_of_coeff_one {c : Chain} {Q : Point}
    (hcoeff : ∀ e ∈ c.toList, e.1 = 1) :
    winding c Q = (c.toList.map fun e => if Q ∈ simplex e.2 then (1 : ℤ) else 0).sum

private theorem coplanar_simplex_of_not_affineIndependent (t : Triangle)
    (h : ¬ AffineIndependent ℚ ![(0 : Point), t.v₀, t.v₁, t.v₂]) :
    Coplanar ℚ (simplex t)

private theorem affineIndependent_of_not_coplanar_inter (t : Triangle)
    (K : Set Point) (hKsub : K ⊆ simplex t) (hco : ¬ Coplanar ℚ K) :
    AffineIndependent ℚ ![(0 : Point), t.v₀, t.v₁, t.v₂]

private theorem exists_two_indep_ker (L : Point →ₗ[ℚ] ℚ) (hL : L ≠ 0) :
    ∃ d₁ d₂ : Point, L d₁ = 0 ∧ L d₂ = 0
      ∧ LinearIndependent ℚ ![d₁, d₂]

theorem leaderExists {m : ℕ} (G : Fin m → (Point →ᵃ[ℚ] ℚ)) (K : Set Point)
    {i : Fin m} (hi : Outer2D G K i) :
    ∃ ℓ ∈ leaders G K, {x : Point | G ℓ x = 0} = {x : Point | G i x = 0}

private theorem base_AI_of_apex {p q r : Point}
    (h : AffineIndependent ℚ ![(0 : Point), p, q, r]) :
    AffineIndependent ℚ ![p, q, r]

private theorem conv_subset_crossPlane (a b : Point) :
    convexHull ℚ ({a, b} : Set Point)
      ⊆ {x : Point | (∑ j, (crossProduct a b) j * x j) = 0}

private theorem crossPlane_descale {a b Q : Point} {ρ : ℚ} (hρ : ρ ≠ 0)
    (h : (∑ j, (crossProduct a b) j * (ρ • Q) j) = 0) :
    (∑ j, (crossProduct a b) j * Q j) = 0

theorem rayFaceCross_reduce_model {t : Triangle} (Q d : P3) {f : PFace}
    (hgood : PFaceGood f t) (hint : P3Int d) :
    rayFaceCross f (toH4 Q) (numI3 d) = rfcModel t (P3.toPoint Q) (P3.toPoint d)

theorem hit_at_root {t : Triangle} {Q d : Point} (hden : dotQ (Proof.MeshIntersectJump.faceNormal t) d ≠ 0) {s : ℚ}
    (hmem : lineAt Q d s ∈ triangleSet t) :
    s = (detOrigin t - dotQ (Proof.MeshIntersectJump.faceNormal t) Q) / dotQ (Proof.MeshIntersectJump.faceNormal t) d

theorem resultant_ne' {t : Triangle} (hdet : detOrigin t ≠ 0) {P : Point} {k k' : Fin 4}
    (hkk : k ≠ k') (hnotboth : ¬ ((slot t k).eval P = 0 ∧ (slot t k').eval P = 0)) :
    (slot t k).eval P • (slot t k').n - (slot t k').eval P • (slot t k).n ≠ 0

theorem nbData_covers {M : Mesh} (h : Legacy.Normal (meshChain M)) {X : Point}
    (hX : ∀ m : Fin (nbData M).1, dotQ ((nbData M).2.1 m) X ≠ (nbData M).2.2 m) :
    winding (meshChain M) X = 0 ∨ winding (meshChain M) X = 1

theorem active_at_endpoints {g : Plane2 →ᵃ[ℚ] ℚ} {x1 x2 : Plane2}
    (hx1 : 0 ≤ g x1) (hx2 : 0 ≤ g x2) {a b : ℚ} (ha : 0 < a) (hb : 0 < b)
    (_hab : a + b = 1) (hv : a * g x1 + b * g x2 = 0) : g x1 = 0 ∧ g x2 = 0

private theorem centerMass_eq_of_coeff_one (W : Finset Plane2) (α : Plane2 → ℚ)
    (hα0 : ∀ y ∈ W, 0 ≤ α y) (hα1 : ∑ y ∈ W, α y = 1) (w : Plane2) (hw : w ∈ W)
    (hαw : α w = 1) : W.centerMass α id = w

private theorem mem_convexHull_erase_of_not_extreme (W : Finset Plane2) (w : Plane2)
    (hw : w ∈ W) (hne : w ∉ Set.extremePoints ℚ (convexHull ℚ (↑W : Set Plane2))) :
    w ∈ convexHull ℚ (↑(W.erase w) : Set Plane2)

private theorem convexHull_erase_eq_of_mem (W : Finset Plane2) (w : Plane2)
    (hwin : w ∈ convexHull ℚ (↑(W.erase w) : Set Plane2)) :
    convexHull ℚ (↑(W.erase w) : Set Plane2) = convexHull ℚ (↑W : Set Plane2)

private theorem subset_convexHull_of_finite_generating (Pset Vx : Set Plane2)
    (hext_sub : Set.extremePoints ℚ Pset ⊆ Vx) :
    ∀ (W : Finset Plane2), convexHull ℚ (↑W : Set Plane2) = Pset → Pset ⊆ convexHull ℚ Vx

private theorem clearPlane_a (n : P3) (c : ℚ) :
    (clearPlane n c).a
      = ((Int.ofNat (((n.x.den.lcm n.y.den).lcm n.z.den).lcm c.den) : ℚ) * n.x).num

private theorem clearPlane_b (n : P3) (c : ℚ) :
    (clearPlane n c).b
      = ((Int.ofNat (((n.x.den.lcm n.y.den).lcm n.z.den).lcm c.den) : ℚ) * n.y).num

private theorem clearPlane_c (n : P3) (c : ℚ) :
    (clearPlane n c).c
      = ((Int.ofNat (((n.x.den.lcm n.y.den).lcm n.z.den).lcm c.den) : ℚ) * n.z).num

private theorem clearPlane_d (n : P3) (c : ℚ) :
    (clearPlane n c).d
      = ((Int.ofNat (((n.x.den.lcm n.y.den).lcm n.z.den).lcm c.den) : ℚ) * c).num

theorem exists_separating_box {t : Triangle} (hn : faceNormal t ≠ 0) {Q : Point}
    (hQ : Q ∉ triangleSet t) :
    ∃ r : ℚ, 0 < r ∧ ∀ P, P ∈ Box Q r → P ∉ triangleSet t

theorem exists_relint_in_box {f : Triangle} (hn : faceNormal f ≠ 0) {Q : Point}
    (hQ : Q ∈ triangleSet f) {r : ℚ} (hr : 0 < r) :
    ∃ x, x ∈ triangleSet f ∧ x ∉ edgeSet f ∧ x ∈ Box Q r

theorem relint_isolated {M : Mesh} (hnfic : NoFaceInteriorContact M) {i : Fin M.size}
    {x : Point} (hxi : x ∈ triangleSet M[i]) (hxe : x ∉ edgeSet M[i])
    {j : Fin M.size} (hji : j ≠ i) : x ∉ triangleSet M[j]

private theorem fin_succ_mk {m : ℕ} [NeZero m] (hm : 3 ≤ m) {a b : ℕ}
    (ha : a < m) (hb : b < m) (hab : (a + 1) % m = b) :
    (⟨a, ha⟩ : Fin m) + 1 = ⟨b, hb⟩

private theorem anchor_val (x a : ℚ) :
    ((x.num * (a.den : ℤ) - a.num * (x.den : ℤ) : ℤ) : ℚ)
      / (((a.den : ℤ) * (x.den : ℤ) : ℤ) : ℚ) = x - a

private theorem winding_eq_finSum (w : Chain) (Q : Point) :
    winding w Q
      = ∑ i : Fin w.size, (if Q ∈ simplex w[i].2 then w[i].1 else 0)

private theorem winding_eq_finSum_indicator (w : Chain) (Q : Point) :
    winding w Q
      = ∑ i : Fin w.size, w[i].1 * (if Q ∈ simplex w[i].2 then (1 : ℤ) else 0)

theorem cross_eq_zero_iff_not_linearIndependent {u v : Fin 2 → ℚ}
    (_hu : u ≠ 0) (hv : v ≠ 0) :
    cross u v = 0 ↔ ¬ LinearIndependent ℚ ![u, v]

theorem rect_pair_bound {n a b : Point} {lam s S : ℚ}
    (hlam : |lam| ≤ 1) (hs : |s| ≤ S) :
    |dotQ n (lam • a + s • b)| ≤ |dotQ n a| + S * |dotQ n b|

theorem originPlane_isPlane {p' q' : Point}
    (h : LinearIndependent ℚ ![p', q']) :
    IsPlane {x : Point | (∑ i, (crossProduct p' q') i * x i) = 0}

theorem coplanar_subset_isPlane {K : Set Point}
    (hco : Coplanar ℚ K) (hne : K.Nonempty) :
    ∃ H : Set Point, IsPlane H ∧ K ⊆ H

theorem box_disjoint_vpoly_disjoint {g g' : Frag}
    (hov : Impl.BVH.overlap (fragBox g) (fragBox g') = false) :
    vpoly (fragCycle g) ∩ vpoly (fragCycle g') = ∅

theorem sorted_nodup_sublist_range {idxs : List Nat} {n : Nat}
    (hs : List.Sorted (· ≤ ·) idxs) (hnd : idxs.Nodup) (hsub : ∀ i ∈ idxs, i < n) :
    idxs.Sublist (List.range n)

private theorem stP_outerStepA {nt : Point} {ct : ℚ} {fa : Frag} (_hfa : FragInv nt ct fa)
    (st : Array Frag × Array Frag) (fb : Frag) (hst : StP nt ct fa st) :
    StP nt ct fa (outerStepA fa st fb)

private theorem stP_outerStepB {nt : Point} {ct : ℚ} {fb : Frag} (_hfb : FragInv nt ct fb)
    (st : Array Frag × Array Frag) (fa : Frag) (hst : StP nt ct fb st) :
    StP nt ct fb (outerStepB fb st fa)

private theorem exC_mem {M : Mesh} {i : Fin M.size} {Φ : List (Point × ℚ)}
    {φ : Point × ℚ} (hφ : φ ∈ Φ) (hz : dotQ φ.1 (Proof.MeshIntersectJump.faceNormal M[i]) = 0) :
    φ ∈ exAll M i Φ

private theorem exAll_perp {M : Mesh} (hnpo : NoPlaneThroughOrigin M)
    {i : Fin M.size} {Φ : List (Point × ℚ)} (hΦ : ∀ φ ∈ Φ, φ.1 ≠ 0) :
    ∀ h ∈ exAll M i Φ, h.1 ≠ 0 ∧ dotQ h.1 (Proof.MeshIntersectJump.faceNormal M[i]) = 0

