    (hns : NoFaceInteriorContact M) {i : Fin M.size} {s : ℤ} {x : Point}
    (hx : AdmPt M i s x) : germValue M i s = winding (meshChain M) x

theorem cross_parallel_normal {n p q r : Point} {c : ℚ}
    (hp : dotQ n p = c) (hq : dotQ n q = c) (hr : dotQ n r = c) :
    dotQ n n • crossQ (q - p) (r - p) = dotQ n (crossQ (q - p) (r - p)) • n

theorem det3_mul_normSq {n p q r : Point} {c : ℚ}
    (hp : dotQ n p = c) (hq : dotQ n q = c) (hr : dotQ n r = c) :
    det3 p q r * dotQ n n = dotQ n (crossQ (q - p) (r - p)) * c

