    winding (meshChain M) Q = 0 ∨ winding (meshChain M) Q = 1

theorem winding_zero_or_one_facets {M : Mesh}
    (hnpo : NoPlaneThroughOrigin M) (hnorm : Legacy.Normal (meshChain M)) {Q : Point}
    (hoff : ∀ i : Fin M.size, ∀ g ∈ tetraHalves M[i], g.eval Q ≠ 0) :
    winding (meshChain M) Q = 0 ∨ winding (meshChain M) Q = 1

