theorem Excludes.forall_mem_list {α : Type*} {l : List α}
    {F : α → Point → Prop} (h : ∀ x ∈ l, Excludes (F x)) :
    Excludes (fun Q => ∀ x ∈ l, F x Q)

theorem Excludes.forall_mem_array {α : Type*} {a : Array α}
    {F : α → Point → Prop} (h : ∀ x ∈ a, Excludes (F x)) :
    Excludes (fun Q => ∀ x ∈ a, F x Q)

theorem mem_planesForScoped_inv {P : IPlane} {B : Array FaceS} {cand : Array Nat}
    {pg : IPlane × Box3} (hpg : pg ∈ planesForScoped P B cand) :
    ∃ j ∈ cand, ∃ box, pg = ((B.getD j default).plane, box)

theorem hit_on_carrier {nt : Point} {ct : ℚ} {Q : Point}
    (hQ : dotQ nt Q ≠ 0) :
    dotQ nt ((ct / dotQ nt Q) • Q) = ct

theorem solid_eq_exists_ray (M : Mesh) (h : WellFormedMesh M) :
    solid M = { Q | (∀ i : Fin M.size, Q ∉ triangleSet M[i]) ∧
      ∃ d, AdmissibleRay M Q d ∧ crossingCount M Q d ≠ 0 }

theorem triangleSet_subset_seg_of_between {a b c : Point}
    (hbetween : b ∈ segment ℚ a c) :
    convexHull ℚ ({a, b, c} : Set Point) ⊆ segment ℚ a c

theorem hit_on_carrier {MB : Mesh} {P dir : Point} {u : Fin MB.size}
    (hden : dotQ (Proof.MeshIntersectJump.faceNormal MB[u]) dir ≠ 0) :
    dotQ (Proof.MeshIntersectJump.faceNormal MB[u]) (lineAt P dir (faceRoot MB P dir u)) = detOrigin MB[u]

theorem wedge_eq_zero_iff {f : PFace} (hw : 0 < f.h0.w) {di : I3}
    (hDn : dotI f.nrmI di ≠ 0) (W : ℤ) :
    f.h0.w * dotI f.nrmI f.nrmI * W = 0 ↔ W = 0

theorem rayFaceCross_congr (f : PFace) {qh qh' : H4} {p : P3}
    (h : H4Repr qh p) (h' : H4Repr qh' p) (di : I3) :
    rayFaceCross f qh di = rayFaceCross f qh' di

theorem rayFaceCrossW_congr {f : PFace} (hf : WedgeOK f) {qh qh' : H4} {p : P3}
    (h : H4Repr qh p) (h' : H4Repr qh' p) (di : I3) :
    rayFaceCrossW f qh di = rayFaceCrossW f qh' di

theorem rayFaceCrossW1_congr {f : PFace} (hf : WedgeOK f) {qh qh' : H4} {p : P3}
    (h : H4Repr qh p) (h' : H4Repr qh' p) :
    rayFaceCrossW1 f qh = rayFaceCrossW1 f qh'

private theorem normalStage_iff (M : Mesh)
    (hcyc : IsClosedOrientedSurface M) (hnd : NoDegenerateFaces M) (hns : NoFaceInteriorContact M) :
    Impl.WellFormedCheck.checkNormalCond M = true ↔ WindingZeroOrOne M

private theorem eqOffPlanes_inter {P₁ R₁ P₂ R₂ : Set Point}
    (h₁ : EqOffPlanes P₁ R₁) (h₂ : EqOffPlanes P₂ R₂) :
    EqOffPlanes (P₁ ∩ P₂) (R₁ ∩ R₂)

private theorem legacyWF_trMesh {M : Mesh} (hcyc : IsClosedOrientedSurface M) (hnrm : WindingZeroOrOne M)
    (hnsi : NoFaceInteriorContact M) {O : Point}
    (hO : Legacy.NoPlaneThroughOrigin (Proof.MeshIntersectM2Kit.trMesh O M)) :
    Legacy.WellFormedMesh (Proof.MeshIntersectM2Kit.trMesh O M)

private theorem eqOffPlanes_mem_iff {P R : Set Point} {N : Set Point}
    (hsub : (P \ R) ∪ (R \ P) ⊆ N) {x : Point} (hx : x ∉ N) :
    x ∈ P ↔ x ∈ R

private theorem checkMeshWF_none_iff (mc mo ms mn : String) (M : Mesh) :
    Impl.WellFormedCheck.checkMeshWF mc mo ms mn M = none
      ↔ Impl.WellFormedCheck.checkWellFormed M = true

theorem negligible_union {N₁ N₂ : Set Point}
    (h₁ : Negligible N₁) (h₂ : Negligible N₂) :
    Negligible (N₁ ∪ N₂)

theorem negligible_iUnion_fintype {ι : Type*} [Fintype ι] {N : ι → Set Point}
    (h : ∀ i, Negligible (N i)) :
    Negligible (⋃ i, N i)

theorem clipBySide_fst_hull_nonpos {g : IPlane} {N : Point} {d : ℚ} {nt : Point}
    {ct : ℚ} {f : Frag} (hg : IsMulOf g N d) (hf : FragInv nt ct f)
    {p : Frag} (hp : p ∈ (clipBySide g f).1) :
    vpoly (fragCycle p) ⊆ {x | ce N d x ≤ 0}

theorem coplanarClip_inside_vpoly_subset_fb_free {nt : Point} {ct : ℚ}
    {nt' : Point} {ct' : ℚ} {fa fb : Frag}
    (hfa : FragInv nt ct fa) (hfb : FragInv nt' ct' fb)
    (hplfa : Proof.MeshIntersectClip.OnPlane nt' ct' (fragCycle fa))
    {p : Frag} (hp : p ∈ (coplanarClip fa fb).1) :
    vpoly (fragCycle p) ⊆ vpoly (fragCycle fb)

theorem clipBySide_snd_vrelint_pos {g : IPlane} {N : Point} {d : ℚ} {nt : Point}
    {ct : ℚ} {f : Frag} (hg : IsMulOf g N d) (hf : FragInv nt ct f)
    {p : Frag} (hp : p ∈ (clipBySide g f).2) :
    vrelint (fragCycle p) ⊆ {x | 0 < ce N d x}

theorem coplanarClip_inside_size3 {nt : Point} {ct : ℚ} {fa fb : Frag}
    (hfa : FragInv nt ct fa) {p : Frag} (hp : p ∈ (coplanarClip fa fb).1) :
    3 ≤ p.poly.size

theorem rayLineMeetsBox_of_mem_line {x d : Impl.BVH.Pt} {b : Impl.BVH.Box} {t : ℚ}
    {px py pz : ℚ}
    (hpx : px = x.x + t * d.x) (hpy : py = x.y + t * d.y) (hpz : pz = x.z + t * d.z)
    (hbx : b.lox ≤ px ∧ px ≤ b.hix) (hby : b.loy ≤ py ∧ py ≤ b.hiy)
    (hbz : b.loz ≤ pz ∧ pz ≤ b.hiz) :
    Impl.BVH.rayLineMeetsBox x d b = true

theorem rayLineMeetsBoxFwd_of_mem_ray {x d : Impl.BVH.Pt} {b : Impl.BVH.Box} {t : ℚ}
    (ht : 0 ≤ t) {px py pz : ℚ}
    (hpx : px = x.x + t * d.x) (hpy : py = x.y + t * d.y) (hpz : pz = x.z + t * d.z)
    (hbx : b.lox ≤ px ∧ px ≤ b.hix) (hby : b.loy ≤ py ∧ py ≤ b.hiy)
    (hbz : b.loz ≤ pz ∧ pz ≤ b.hiz) :
    Impl.BVH.rayLineMeetsBoxFwd x d b = true

theorem fracStep_scaled {k : Int} (hk : 0 < k) {acc acc' : Option ((Int × Int) × (Int × Int))}
    (hacc : OptScaled k acc acc') {p p' : Int × Int} (hp : ScaledBy k p p') :
    OptScaled k (fracStep acc p) (fracStep acc' p')

theorem fracInterval_scaled {k : Int} (hk : 0 < k) {ps ps' : Array (Int × Int)}
    (h : List.Forall₂ (ScaledBy k) ps.toList ps'.toList) :
    OptScaled k (fracInterval ps) (fracInterval ps')

theorem isCoplanarWith_clipFace_iff {MA MB : Mesh} (_meshId : Nat) {i : ℕ}
    (hi : i < MA.size) {L : Array (IPlane × Box3)} {f : Frag}
    (hf : f ∈ clipFaceScoped (fragOfFace (faceSOf (MA[i]'hi))) L) :
    (isCoplanarWith f (materialize MB) = false) ↔ TrFace MA MB i hi

theorem filter_clipFace_of_TrFace {MA MB : Mesh} (meshId : Nat) {i : ℕ}
    (hi : i < MA.size) {L : Array (IPlane × Box3)}
    (htr : TrFace MA MB i hi) :
    ((clipFaceScoped (fragOfFace (faceSOf (MA[i]'hi))) L).filter
        (fun f => !(isCoplanarWith f (materialize MB)))).toList
      = (clipFaceScoped (fragOfFace (faceSOf (MA[i]'hi))) L).toList

theorem filter_clipFace_of_not_TrFace {MA MB : Mesh} (meshId : Nat) {i : ℕ}
    (hi : i < MA.size) {L : Array (IPlane × Box3)}
    (htr : ¬ TrFace MA MB i hi) :
    ((clipFaceScoped (fragOfFace (faceSOf (MA[i]'hi))) L).filter
        (fun f => !(isCoplanarWith f (materialize MB)))).toList = []

theorem dotQ_eq_of_mem_vrelint {n : Point} {c : ℚ} {fa : Frag}
    (hfa : FragInv n c fa) {z : Point} (hz : z ∈ vrelint (fragCycle fa)) :
    dotQ n z = c
